import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const {
    scenePlacement,
    imageUrl,
    behaviorSpec,
    textContent,
    cinematicPrimitives,
    atlasRegion,
  } = config;

  // --- Group setup ---
  const group = new THREE.Group();
  group.position.set(...scenePlacement.position);
  group.rotation.set(...scenePlacement.rotation);
  group.scale.set(...scenePlacement.scale);

  // --- Texture ---
  const texture = ctx.textureLoader.load(imageUrl);

  // --- Card dimensions (aspect from atlas source rect) ---
  const srcW = atlasRegion.sourceRect[2]; // 512
  const srcH = atlasRegion.sourceRect[3]; // 320
  const aspect = srcW / srcH;             // 1.6

  // Scene-unit size for the card
  const cardWidth = 2.0;
  const cardHeight = cardWidth / aspect; // ~1.25

  // --- Main card plane ---
  const cardGeo = new THREE.PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshBasicNodeMaterial({ map: texture });
  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.position.z = 0;
  group.add(cardMesh);

  // --- Accent border (hidden by default) ---
  const borderWidth = cardWidth + 0.06;
  const borderHeight = cardHeight + 0.06;
  const borderGeo = new THREE.PlaneGeometry(borderWidth, borderHeight);
  const borderMat = new MeshBasicNodeMaterial({
    color: config.colors?.accent ?? '#ff2a38',
    transparent: true,
    opacity: 0,
    depthWrite: false,
  });
  const borderMesh = new THREE.Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.001; // behind main plane so only edges show
  borderMesh.visible = false;
  group.add(borderMesh);

  // --- Resources for cleanup ---
  const disposables = [cardGeo, cardMat, texture, borderGeo, borderMat];

  // --- GSAP hover timeline (paused) ---
  const hoverTl = gsap.timeline({ paused: true });
  // Lift the whole group up by 0.15 scene units
  hoverTl.to(group.position, {
    y: group.position.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  // Fade in border overlay
  hoverTl.to(borderMat, { opacity: 1, duration: 0.3 }, 0);

  // --- Attach handlers to userData.handlers ---
  group.userData.handlers = {
    hoverStart: () => {
      borderMesh.visible = true;
      hoverTl.play();
    },
    hoverEnd: () => {
      hoverTl.reverse();
      hoverTl.eventCallback('onReverseComplete', () => {
        borderMesh.visible = false;
      });
    },
    click: () => {
      // Press-down scale animation
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1,
            y: 1,
            duration: 0.3,
            ease: 'power2.out',
          });
        },
      });
      // Emit navigation event
      group.dispatchEvent({ type: 'hub-journal.select', bubbles: true });
    },
  };

  // Store timeline for cleanup
  group.userData.hoverTimeline = hoverTl;

  // --- Apply cinematic primitives ---
  if (cinematicPrimitives && ctx.primitives) {
    cinematicPrimitives.forEach((prim) => {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        fn(group, prim.params);
      }
    });
  }

  // --- Cleanup function ---
  group.userData.cleanup = () => {
    disposables.forEach((d) => d.dispose());
    if (group.userData.hoverTimeline) {
      group.userData.hoverTimeline.kill();
    }
    // Remove children (handled by parent scene disposal)
  };

  return group;
}
